package fixture

import "testing"

func TestSumDigits(t *testing.T) {
	if got := SumDigits(123); got != 6 {
		t.Fatalf("SumDigits(123) = %d, want 6", got)
	}
	if got := SumDigits(-45); got != 9 {
		t.Fatalf("SumDigits(-45) = %d, want 9", got)
	}
}
